const EDITABLE_CAPABLE_BLOCK_TYPES = /* @__PURE__ */ new Set([
  "input_notes",
  "input_task",
  "input_table",
  "input_list",
  // Webpage text may be edited in the picker BEFORE send, but it has no
  // writable backing record. That is snapshot preparation, not agent access.
  // Matrx entities whose underlying record the agent can write back to.
  // Pure references (input_agent, input_agent_app) are intentionally NOT here.
  "input_project",
  "input_transcript",
  "input_workbook",
  "input_document"
]);
function isEditableCapableBlockType(blockType) {
  return EDITABLE_CAPABLE_BLOCK_TYPES.has(blockType);
}
export {
  isEditableCapableBlockType
};
