import { createSlice } from "@reduxjs/toolkit";
const initialState = { byConversationId: {} };
const hostConversationsSlice = createSlice({
  name: "hostConversations",
  initialState,
  reducers: {
    hostConversationBound(state, action) {
      state.byConversationId[action.payload.conversationId] = action.payload.entry;
    },
    hostConversationUnbound(state, action) {
      delete state.byConversationId[action.payload];
    },
    hostConversationHeld(state, action) {
      const entry = state.byConversationId[action.payload.conversationId];
      if (entry) entry.held = action.payload.reason;
    },
    hostConversationUnavailable(state, action) {
      const entry = state.byConversationId[action.payload.conversationId];
      if (entry) entry.unavailable = action.payload.reason;
    }
  }
});
const {
  hostConversationBound,
  hostConversationUnbound,
  hostConversationHeld,
  hostConversationUnavailable
} = hostConversationsSlice.actions;
const hostConversationsReducer = hostConversationsSlice.reducer;
var host_conversations_slice_default = hostConversationsSlice.reducer;
export {
  host_conversations_slice_default as default,
  hostConversationBound,
  hostConversationHeld,
  hostConversationUnavailable,
  hostConversationUnbound,
  hostConversationsReducer
};
