import { productionUrl } from "../../host/server/endpoints.js";
import {
  buildMatrxRequestUrl,
  readMatrxJsonResponse,
  sendMatrxRequest
} from "@ai-matrx/agents/matrx";
import { applyOrganizationContextHeader } from "../../host/server/organization-context.js";
import { ensureOrganizationForRequest } from "../../host/org.js";
import { readSessionToken } from "../../host/identity.js";
function backendBase() {
  return productionUrl();
}
async function authHeaders(method, explicitOrganizationId) {
  const accessToken = await readSessionToken();
  if (!accessToken) throw new Error("Not signed in");
  const organizationId = await ensureOrganizationForRequest({
    method,
    organizationId: explicitOrganizationId
  });
  return applyOrganizationContextHeader(
    {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json"
    },
    organizationId
  );
}
async function mcpFetch(path, init, explicitOrganizationId) {
  const headers = await authHeaders(init?.method ?? "GET", explicitOrganizationId);
  let resp;
  try {
    resp = await sendMatrxRequest(
      buildMatrxRequestUrl(backendBase(), `/api/mcp-connections${path}`),
      { ...init, headers: { ...headers, ...init?.headers } }
    );
  } catch (error) {
    if (error instanceof DOMException && error.name === "AbortError") throw error;
    throw new Error("MCP service unreachable \u2014 the backend must be online");
  }
  return readMatrxJsonResponse(resp);
}
function fetchMcpAvailability(organizationId, slugs) {
  const query = slugs && slugs.length > 0 ? `?slugs=${encodeURIComponent(slugs.join(","))}` : "";
  return mcpFetch(
    `/availability${query}`,
    void 0,
    organizationId
  );
}
async function discoverMcpServerTools(serverId) {
  const resp = await mcpFetch(`/${encodeURIComponent(serverId)}/tools`);
  return {
    serverId: resp.server_id,
    serverSlug: resp.server_slug,
    tools: resp.tools.map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: t.parameters ?? {}
    }))
  };
}
function invokeMcpServerTool(serverId, toolName, args) {
  return mcpFetch(
    `/${encodeURIComponent(serverId)}/invoke`,
    {
      method: "POST",
      body: JSON.stringify({ tool_name: toolName, arguments: args ?? {} })
    }
  );
}
function refreshMcpConnection(serverId) {
  return mcpFetch(`/${encodeURIComponent(serverId)}/refresh`, {
    method: "POST"
  });
}
function refreshMcpCatalog(serverId) {
  return mcpFetch(`/${encodeURIComponent(serverId)}/catalog-refresh`, {
    method: "POST"
  });
}
function persistMcpManualCredentials(serverId, body) {
  return mcpFetch(`/${encodeURIComponent(serverId)}/credentials`, {
    method: "POST",
    body: JSON.stringify(body)
  });
}
function disconnectMcpConnection(serverId) {
  return mcpFetch(`/${encodeURIComponent(serverId)}`, { method: "DELETE" });
}
function headerFieldKey(headerName) {
  const normalized = headerName.toLowerCase().replace(/[^a-z0-9]/g, "_");
  return `header_${normalized}`;
}
export {
  disconnectMcpConnection,
  discoverMcpServerTools,
  fetchMcpAvailability,
  headerFieldKey,
  invokeMcpServerTool,
  persistMcpManualCredentials,
  refreshMcpCatalog,
  refreshMcpConnection
};
