import { createSelector } from "@reduxjs/toolkit";
const EMPTY_INSTANCES = [];
const EMPTY_CONVERSATION_IDS_BY_AGENT = {};
const selectInstance = (conversationId) => (state) => state.conversations.byConversationId[conversationId];
const selectAllConversationIds = (state) => state.conversations.allConversationIds;
const selectAllInstanceIds = selectAllConversationIds;
const selectConversationIdsByAgent = createSelector(
  (state) => state.conversations.allConversationIds,
  (state) => state.conversations.byConversationId,
  (allIds, byId) => {
    const map = {};
    for (const cid of allIds) {
      const inst = byId[cid];
      if (!inst) continue;
      const aid = inst.agentId;
      if (!map[aid]) map[aid] = [];
      map[aid].push(cid);
    }
    return Object.keys(map).length === 0 ? EMPTY_CONVERSATION_IDS_BY_AGENT : map;
  }
);
const selectInstancesByAgent = (agentId) => createSelector(
  (state) => state.conversations.allConversationIds,
  (state) => state.conversations.byConversationId,
  (allIds, byId) => {
    const result = allIds.map((id) => byId[id]).filter((inst) => inst?.agentId === agentId);
    return result.length === 0 ? EMPTY_INSTANCES : result;
  }
);
const selectConversationSurfaceOwnsOutput = createSelector(
  (state, conversationId) => conversationId ? state.conversations.byConversationId[conversationId] : void 0,
  (record) => record?.surfaceOwnsOutput === true
);
const selectInstanceStatus = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.status;
const selectRunningInstances = createSelector(
  (state) => state.conversations.allConversationIds,
  (state) => state.conversations.byConversationId,
  (allIds, byId) => {
    const result = allIds.map((id) => byId[id]).filter(
      (inst) => inst != null && (inst.status === "running" || inst.status === "streaming")
    );
    return result.length === 0 ? EMPTY_INSTANCES : result;
  }
);
const selectAgentIdFromInstance = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.agentId;
const selectIsCacheOnly = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.cacheOnly ?? true;
const selectConversationTitle = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.title ?? null;
const selectConversationDescription = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.description ?? null;
const selectConversationKeywords = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.keywords ?? null;
const selectConversationIsEphemeral = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.isEphemeral ?? false;
const selectApiEndpointMode = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.apiEndpointMode ?? null;
const selectConversationSurfaceKey = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.surfaceKey ?? null;
const selectConversationSandboxBinding = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.sandboxBinding ?? null;
const selectConversationSandboxPersisted = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.sandboxBindingPersisted ?? false;
const selectConversationScopeIds = (conversationId) => createSelector(
  (state) => state.conversations.byConversationId[conversationId],
  (record) => ({
    organizationId: record?.organizationId ?? null,
    projectId: record?.projectId ?? null,
    taskId: record?.taskId ?? null
  })
);
const selectViewerCanReply = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.viewerCanReply !== false;
const selectConversationOrganizationId = (conversationId) => (state) => state.conversations.byConversationId[conversationId]?.organizationId ?? null;
export {
  selectAgentIdFromInstance,
  selectAllConversationIds,
  selectAllInstanceIds,
  selectApiEndpointMode,
  selectConversationDescription,
  selectConversationIdsByAgent,
  selectConversationIsEphemeral,
  selectConversationKeywords,
  selectConversationOrganizationId,
  selectConversationSandboxBinding,
  selectConversationSandboxPersisted,
  selectConversationScopeIds,
  selectConversationSurfaceKey,
  selectConversationSurfaceOwnsOutput,
  selectConversationTitle,
  selectInstance,
  selectInstanceStatus,
  selectInstancesByAgent,
  selectIsCacheOnly,
  selectRunningInstances,
  selectViewerCanReply
};
