import { createSlice } from "@reduxjs/toolkit";
const initialState = {
  revisionByConversationId: {},
  lastDeltaByConversationId: {}
};
const activeToolsSlice = createSlice({
  name: "activeTools",
  initialState,
  reducers: {
    invalidateActiveTools(state, action) {
      const { conversationId, added = 0, removed = 0 } = action.payload;
      state.revisionByConversationId[conversationId] = (state.revisionByConversationId[conversationId] ?? 0) + 1;
      state.lastDeltaByConversationId[conversationId] = { added, removed };
    },
    clearActiveTools(state, action) {
      delete state.revisionByConversationId[action.payload.conversationId];
      delete state.lastDeltaByConversationId[action.payload.conversationId];
    }
  }
});
const { invalidateActiveTools, clearActiveTools } = activeToolsSlice.actions;
const activeToolsReducer = activeToolsSlice.reducer;
function selectActiveToolsRevision(state, conversationId) {
  return state.activeTools.revisionByConversationId[conversationId] ?? 0;
}
function selectActiveToolsLastDelta(state, conversationId) {
  return state.activeTools.lastDeltaByConversationId[conversationId] ?? null;
}
export {
  activeToolsReducer,
  clearActiveTools,
  invalidateActiveTools,
  selectActiveToolsLastDelta,
  selectActiveToolsRevision
};
