import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { chatHostHasDatabase } from "../../../host/configure.js";
import {
  fetchMcpCatalog,
  connectMcpServer as connectMcpServerService
} from "../../services/mcp.service.js";
import {
  disconnectMcpConnection,
  fetchMcpAvailability,
  discoverMcpServerTools,
  persistMcpManualCredentials,
  refreshMcpConnection
} from "../../services/mcp-connections.service.js";
const initialState = {
  catalog: [],
  status: "idle",
  error: null,
  connectingServerId: null,
  discoveries: {},
  availability: {},
  availabilityOrganizationId: null,
  availabilityStatus: "idle",
  availabilityError: null
};
const EMPTY_MCP_AVAILABILITY = {};
const NEEDS_DATABASE = { condition: () => chatHostHasDatabase() };
const fetchCatalog = createAsyncThunk("mcp/fetchCatalog", async () => {
  return fetchMcpCatalog();
}, NEEDS_DATABASE);
const fetchAvailability = createAsyncThunk(
  "mcp/fetchAvailability",
  async ({ organizationId, slugs }) => fetchMcpAvailability(organizationId, slugs),
  NEEDS_DATABASE
);
const connectServer = createAsyncThunk(
  "mcp/connectServer",
  async (params, { dispatch }) => {
    const connectionId = await connectMcpServerService(params);
    dispatch(fetchCatalog());
    return { serverId: params.serverId, connectionId };
  },
  NEEDS_DATABASE
);
const connectServerWithCredentials = createAsyncThunk(
  "mcp/connectServerWithCredentials",
  async (params, { dispatch }) => {
    const summary = await persistMcpManualCredentials(params.serverId, {
      auth_method: params.authMethod,
      fields: params.fields,
      transport: params.transport,
      config_id: params.configId,
      endpoint_override: params.endpointOverride
    });
    dispatch(fetchCatalog());
    return { serverId: params.serverId, connectionId: summary.connection_id };
  },
  NEEDS_DATABASE
);
const disconnectServer = createAsyncThunk(
  "mcp/disconnectServer",
  async (serverId, { dispatch }) => {
    await disconnectMcpConnection(serverId);
    dispatch(fetchCatalog());
    return serverId;
  },
  NEEDS_DATABASE
);
const discoverServerTools = createAsyncThunk(
  "mcp/discoverServerTools",
  async (serverId) => {
    const resp = await discoverMcpServerTools(serverId);
    return {
      serverId: resp.serverId,
      serverSlug: resp.serverSlug,
      tools: resp.tools,
      resources: [],
      prompts: []
    };
  },
  NEEDS_DATABASE
);
const refreshServerToken = createAsyncThunk(
  "mcp/refreshServerToken",
  async (serverId) => {
    await refreshMcpConnection(serverId);
    return serverId;
  },
  NEEDS_DATABASE
);
const mcpSlice = createSlice({
  name: "mcp",
  initialState,
  reducers: {
    clearMcpError(state) {
      state.error = null;
    },
    updateCatalogEntry(state, action) {
      const idx = state.catalog.findIndex(
        (e) => e.serverId === action.payload.serverId
      );
      if (idx !== -1) {
        state.catalog[idx] = { ...state.catalog[idx], ...action.payload.patch };
      }
    },
    clearServerDiscovery(state, action) {
      delete state.discoveries[action.payload];
    }
  },
  extraReducers: (builder) => {
    builder.addCase(fetchCatalog.pending, (state) => {
      state.status = "loading";
      state.error = null;
    }).addCase(fetchCatalog.fulfilled, (state, action) => {
      state.status = "succeeded";
      state.catalog = action.payload;
    }).addCase(fetchCatalog.rejected, (state, action) => {
      state.status = "failed";
      state.error = action.error.message ?? "Failed to fetch MCP catalog";
    }).addCase(fetchAvailability.pending, (state, action) => {
      state.availabilityOrganizationId = action.meta.arg.organizationId;
      state.availability = {};
      state.availabilityStatus = "loading";
      state.availabilityError = null;
    }).addCase(fetchAvailability.fulfilled, (state, action) => {
      if (state.availabilityOrganizationId !== action.meta.arg.organizationId)
        return;
      state.availabilityStatus = "succeeded";
      for (const row of action.payload) {
        state.availability[row.slug] = row;
      }
    }).addCase(fetchAvailability.rejected, (state, action) => {
      if (state.availabilityOrganizationId !== action.meta.arg.organizationId)
        return;
      state.availabilityStatus = "failed";
      state.availabilityError = action.error.message ?? "Could not check MCP connection health";
    }).addCase(connectServer.pending, (state, action) => {
      state.connectingServerId = action.meta.arg.serverId;
    }).addCase(connectServer.fulfilled, (state) => {
      state.connectingServerId = null;
    }).addCase(connectServer.rejected, (state, action) => {
      state.connectingServerId = null;
      state.error = action.error.message ?? "Failed to connect MCP server";
    }).addCase(connectServerWithCredentials.pending, (state, action) => {
      state.connectingServerId = action.meta.arg.serverId;
    }).addCase(connectServerWithCredentials.fulfilled, (state) => {
      state.connectingServerId = null;
    }).addCase(connectServerWithCredentials.rejected, (state, action) => {
      state.connectingServerId = null;
      state.error = action.error.message ?? "Failed to connect MCP server";
    }).addCase(disconnectServer.fulfilled, (state, action) => {
      const idx = state.catalog.findIndex(
        (e) => e.serverId === action.payload
      );
      if (idx !== -1) {
        state.catalog[idx] = {
          ...state.catalog[idx],
          connectionStatus: "disconnected",
          connectionId: null
        };
      }
      delete state.discoveries[action.payload];
    }).addCase(discoverServerTools.pending, (state, action) => {
      state.discoveries[action.meta.arg] = {
        tools: [],
        resources: [],
        prompts: [],
        status: "loading",
        error: null,
        discoveredAt: null
      };
    }).addCase(discoverServerTools.fulfilled, (state, action) => {
      state.discoveries[action.meta.arg] = {
        tools: action.payload.tools,
        resources: action.payload.resources,
        prompts: action.payload.prompts,
        status: "succeeded",
        error: null,
        discoveredAt: (/* @__PURE__ */ new Date()).toISOString()
      };
    }).addCase(discoverServerTools.rejected, (state, action) => {
      const existing = state.discoveries[action.meta.arg];
      state.discoveries[action.meta.arg] = {
        tools: existing?.tools ?? [],
        resources: existing?.resources ?? [],
        prompts: existing?.prompts ?? [],
        status: "failed",
        error: action.error.message ?? "Discovery failed",
        discoveredAt: existing?.discoveredAt ?? null
      };
    });
  }
});
const { clearMcpError, updateCatalogEntry, clearServerDiscovery } = mcpSlice.actions;
var mcp_slice_default = mcpSlice.reducer;
const selectMcpState = (state) => state.mcp;
const selectMcpCatalog = (state) => selectMcpState(state).catalog;
const selectMcpCatalogStatus = (state) => selectMcpState(state).status;
const selectMcpCatalogError = (state) => selectMcpState(state).error;
const selectMcpConnectingServerId = (state) => selectMcpState(state).connectingServerId;
const selectMcpServerById = (state, serverId) => selectMcpState(state).catalog.find((e) => e.serverId === serverId) ?? null;
const selectMcpCatalogByCategory = (state) => {
  const catalog = selectMcpState(state).catalog;
  const grouped = {};
  for (const entry of catalog) {
    if (!grouped[entry.category]) grouped[entry.category] = [];
    grouped[entry.category].push(entry);
  }
  return grouped;
};
const selectMcpDiscoveries = (state) => selectMcpState(state).discoveries;
const selectMcpServerDiscovery = (state, serverId) => selectMcpState(state).discoveries[serverId] ?? null;
const EMPTY_MCP_TOOLS = [];
const selectMcpServerTools = (state, serverId) => selectMcpState(state).discoveries[serverId]?.tools ?? EMPTY_MCP_TOOLS;
const selectMcpServerDiscoveryStatus = (state, serverId) => selectMcpState(state).discoveries[serverId]?.status ?? "idle";
const selectAllDiscoveredMcpTools = (state) => {
  const discoveries = selectMcpState(state).discoveries;
  const allTools = [];
  for (const [serverId, discovery] of Object.entries(discoveries)) {
    if (discovery.status !== "succeeded") continue;
    const catalogEntry = state.mcp.catalog.find((e) => e.serverId === serverId);
    const serverName = catalogEntry?.name ?? serverId;
    for (const tool of discovery.tools) {
      allTools.push({ ...tool, serverId, serverName });
    }
  }
  return allTools;
};
const selectMcpAvailability = (state) => selectMcpState(state).availability;
const selectMcpAvailabilityForOrganization = (state, organizationId) => organizationId && selectMcpState(state).availabilityOrganizationId === organizationId ? selectMcpState(state).availability : EMPTY_MCP_AVAILABILITY;
const selectMcpAvailabilityStatus = (state) => selectMcpState(state).availabilityStatus;
const selectMcpAvailabilityStatusForOrganization = (state, organizationId) => organizationId && selectMcpState(state).availabilityOrganizationId === organizationId ? selectMcpState(state).availabilityStatus : "idle";
const selectMcpAvailabilityError = (state) => selectMcpState(state).availabilityError;
export {
  clearMcpError,
  clearServerDiscovery,
  connectServer,
  connectServerWithCredentials,
  mcp_slice_default as default,
  disconnectServer,
  discoverServerTools,
  fetchAvailability,
  fetchCatalog,
  refreshServerToken,
  selectAllDiscoveredMcpTools,
  selectMcpAvailability,
  selectMcpAvailabilityError,
  selectMcpAvailabilityForOrganization,
  selectMcpAvailabilityStatus,
  selectMcpAvailabilityStatusForOrganization,
  selectMcpCatalog,
  selectMcpCatalogByCategory,
  selectMcpCatalogError,
  selectMcpCatalogStatus,
  selectMcpConnectingServerId,
  selectMcpDiscoveries,
  selectMcpServerById,
  selectMcpServerDiscovery,
  selectMcpServerDiscoveryStatus,
  selectMcpServerTools,
  updateCatalogEntry
};
