import { Bot, MessageSquare, Puzzle, Timer, Workflow } from "lucide-react";
const HIDDEN_CONVERSATION_LANE = "hidden";
const CONVERSATION_LANES = [
  "chat",
  "matrx",
  "auto",
  "plugin",
  "subagent"
];
const LANE_META = {
  chat: {
    label: "Chat",
    icon: MessageSquare,
    description: "Chats you started with an agent you picked"
  },
  matrx: {
    label: "Matrx",
    icon: Workflow,
    description: "Everything else you started in AI Matrx"
  },
  auto: {
    label: "Auto",
    icon: Timer,
    description: "Scheduled, workflow, system and automatic runs"
  },
  plugin: {
    label: "Plugins",
    icon: Puzzle,
    description: "Mirrored from Claude Code, Codex, Cursor and VS Code"
  },
  subagent: {
    label: "Subagents",
    icon: Bot,
    description: "Sub-agents spawned by an agent or a plugin"
  }
};
const DEFAULT_CONVERSATION_LANES = [
  "chat",
  "matrx"
];
function isConversationLane(value) {
  return typeof value === "string" && CONVERSATION_LANES.includes(value);
}
function normalizeLanes(value) {
  if (!Array.isArray(value)) return [...DEFAULT_CONVERSATION_LANES];
  const set = new Set(value.filter(isConversationLane));
  return CONVERSATION_LANES.filter((l) => set.has(l));
}
function toggleLane(lanes, lane) {
  const set = new Set(lanes);
  if (set.has(lane)) set.delete(lane);
  else set.add(lane);
  return CONVERSATION_LANES.filter((l) => set.has(l));
}
const CHAT_LANE_FEATURES = [
  "chat",
  "agent-runner",
  "agent-builder",
  "agent-app",
  "agent-comparison",
  "agent-generator",
  "agents-other",
  "voice-agent"
];
function laneOfClientMintedRow(sourceFeature, originClass) {
  if (originClass === "client_auto") return "auto";
  return sourceFeature && CHAT_LANE_FEATURES.includes(sourceFeature) ? "chat" : "matrx";
}
export {
  CHAT_LANE_FEATURES,
  CONVERSATION_LANES,
  DEFAULT_CONVERSATION_LANES,
  HIDDEN_CONVERSATION_LANE,
  LANE_META,
  isConversationLane,
  laneOfClientMintedRow,
  normalizeLanes,
  toggleLane
};
