import { createSlice } from "@reduxjs/toolkit";
const RUN_SET_MAX_ENTRIES = 20;
const initialState = { bySetKey: {} };
const runSetsSlice = createSlice({
  name: "runSets",
  initialState,
  reducers: {
    /** INTERNAL — dispatch via addRunToSet (it also places the set hold). */
    runSetEntryAdded(state, action) {
      const { setKey, entry } = action.payload;
      const entries = state.bySetKey[setKey] ?? [];
      const existing = entries.findIndex((item) => item.id === entry.id);
      if (existing >= 0) {
        entries[existing] = { ...entries[existing], label: entry.label };
      } else {
        entries.push(entry);
      }
      state.bySetKey[setKey] = entries;
    },
    /** INTERNAL — dispatch via removeRunSetEntry / clearRunSet. */
    runSetEntryRemoved(state, action) {
      const { setKey, id } = action.payload;
      const entries = state.bySetKey[setKey];
      if (!entries) return;
      const remaining = entries.filter((item) => item.id !== id);
      if (remaining.length === 0) {
        delete state.bySetKey[setKey];
      } else {
        state.bySetKey[setKey] = remaining;
      }
    },
    /** INTERNAL — dispatch via clearRunSet. */
    runSetCleared(state, action) {
      delete state.bySetKey[action.payload.setKey];
    }
  }
});
const { runSetEntryAdded, runSetEntryRemoved, runSetCleared } = runSetsSlice.actions;
var run_sets_slice_default = runSetsSlice.reducer;
const EMPTY_ENTRIES = [];
const selectRunSetEntries = (state, setKey) => state.runSets.bySetKey[setKey] ?? EMPTY_ENTRIES;
export {
  RUN_SET_MAX_ENTRIES,
  run_sets_slice_default as default,
  runSetCleared,
  runSetEntryAdded,
  runSetEntryRemoved,
  selectRunSetEntries
};
