"use client";
import { createSlice } from "@reduxjs/toolkit";
const initialState = {
  list: [],
  listLoaded: false,
  listStatus: "idle",
  listError: null,
  valuesBySurface: {},
  valuesLoaded: {},
  valuesStatus: {},
  valuesError: {}
};
const surfacesCatalogSlice = createSlice({
  name: "surfacesCatalog",
  initialState,
  reducers: {
    setListStatus(state, action) {
      state.listStatus = action.payload;
    },
    setListError(state, action) {
      state.listError = action.payload;
    },
    setSurfaces(state, action) {
      state.list = action.payload;
      state.listLoaded = true;
      state.listStatus = "succeeded";
      state.listError = null;
    },
    setValuesStatus(state, action) {
      state.valuesStatus[action.payload.surfaceName] = action.payload.status;
    },
    setValuesError(state, action) {
      state.valuesError[action.payload.surfaceName] = action.payload.error;
    },
    setValuesForSurface(state, action) {
      const { surfaceName, values } = action.payload;
      state.valuesBySurface[surfaceName] = values;
      state.valuesLoaded[surfaceName] = true;
      state.valuesStatus[surfaceName] = "succeeded";
      state.valuesError[surfaceName] = null;
    },
    clearCatalog(state) {
      state.list = [];
      state.listLoaded = false;
      state.listStatus = "idle";
      state.listError = null;
      state.valuesBySurface = {};
      state.valuesLoaded = {};
      state.valuesStatus = {};
      state.valuesError = {};
    }
  }
});
const {
  setListStatus,
  setListError,
  setSurfaces,
  setValuesStatus,
  setValuesError,
  setValuesForSurface,
  clearCatalog
} = surfacesCatalogSlice.actions;
const surfacesCatalogReducer = surfacesCatalogSlice.reducer;
var surfacesCatalogSlice_default = surfacesCatalogReducer;
export {
  clearCatalog,
  surfacesCatalogSlice_default as default,
  setListError,
  setListStatus,
  setSurfaces,
  setValuesError,
  setValuesForSurface,
  setValuesStatus,
  surfacesCatalogReducer
};
