import { supabase } from "../../host/db.js";
import {
  catalogEntryFromRpc,
  serverConfigFromRow
} from "../types/mcp.types.js";
import { runWithSessionRetry } from "../../host/session-retry.js";
import { requireSelectedOrgId, withOrganizationRefusalShown } from "../../host/org.js";
async function fetchMcpCatalog() {
  const { data, error } = await runWithSessionRetry(
    () => supabase.rpc("get_mcp_catalog_for_user")
  );
  if (error) throw new Error(`Failed to fetch MCP catalog: ${error.message}`);
  if (!data) return [];
  return data.map(catalogEntryFromRpc);
}
async function connectMcpServer(params) {
  return withOrganizationRefusalShown("connected", async () => {
    const { data, error } = await supabase.rpc("upsert_mcp_connection", {
      p_server_id: params.serverId,
      p_config_id: params.configId,
      p_transport: params.transport,
      p_endpoint_override: params.endpointOverride,
      // A NEW connection is filed in the organization the person is working in —
      // named explicitly, never chosen by the database (the row stays personal).
      p_organization_id: requireSelectedOrgId()
      // org-filter: write-target a NEW MCP connection is filed in the organization the person works in
    });
    if (error) throw new Error(`Failed to connect MCP server: ${error.message}`);
    return data;
  });
}
async function fetchMcpServerConfigs(serverId) {
  const { data, error } = await supabase.schema("tool").from("mcp_config").select("*").eq("server_id", serverId).is("deleted_at", null).order("is_default", { ascending: false });
  if (error)
    throw new Error(`Failed to fetch MCP server configs: ${error.message}`);
  if (!data) return [];
  return data.map(serverConfigFromRow);
}
export {
  connectMcpServer,
  fetchMcpCatalog,
  fetchMcpServerConfigs
};
