import { createSlice } from "@reduxjs/toolkit";
const initialState = {
  isActive: false
};
const chatIncognitoSlice = createSlice({
  name: "chatIncognito",
  initialState,
  reducers: {
    setChatIncognitoActive(state, action) {
      state.isActive = action.payload;
    },
    toggleChatIncognito(state) {
      state.isActive = !state.isActive;
    }
  }
});
const { setChatIncognitoActive, toggleChatIncognito } = chatIncognitoSlice.actions;
var chat_incognito_slice_default = chatIncognitoSlice.reducer;
const selectChatIncognitoActive = (state) => state.chatIncognito.isActive;
export {
  chat_incognito_slice_default as default,
  selectChatIncognitoActive,
  setChatIncognitoActive,
  toggleChatIncognito
};
