import { createSelector, createSlice } from "@reduxjs/toolkit";
const initialState = { byConversation: {} };
const proposedDirectivesSlice = createSlice({
  name: "proposedDirectives",
  initialState,
  reducers: {
    proposeDirective(state, action) {
      const { conversationId, proposalId } = action.payload;
      const list = state.byConversation[conversationId] ?? [];
      if (list.some((p) => p.proposalId === proposalId)) return;
      state.byConversation[conversationId] = [...list, action.payload];
    },
    removeProposal(state, action) {
      const { conversationId, proposalId } = action.payload;
      const list = state.byConversation[conversationId];
      if (!list) return;
      const next = list.filter((p) => p.proposalId !== proposalId);
      if (next.length) state.byConversation[conversationId] = next;
      else delete state.byConversation[conversationId];
    },
    /**
     * The user clicked, the server answered: keep the card and turn it into the
     * receipt. NOT `removeProposal` — a card that disappears is how a person
     * ends up unable to tell whether anything happened.
     */
    resolveProposal(state, action) {
      const { conversationId, proposalId, outcome, outcomeMessage } = action.payload;
      const list = state.byConversation[conversationId];
      if (!list) return;
      state.byConversation[conversationId] = list.map(
        (p) => p.proposalId === proposalId ? { ...p, outcome, outcomeMessage } : p
      );
    },
    clearProposalsForConversation(state, action) {
      delete state.byConversation[action.payload];
    }
  }
});
