// models/capabilities.ts
function isManagedAgentModelCapability(capabilities) {
  return capabilities.interaction === "agent";
}
function isDecisionModelCapability(capabilities) {
  return capabilities.interaction === "decision";
}
function acceptsTextInstructions(capabilities) {
  if (capabilities.interaction === "realtime") return true;
  const input = capabilities.input ?? [];
  return input.length === 0 || input.includes("text");
}

